INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1466718-che471', 'stk-user10077', 'CHE 471', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nCHE 471\n\nالمقرر جميل اضاف لي الكثير من المعلومات التي اعتبرها عامة اكثر من كونها هندسية بحتة.\n\nمحتوى المادة تسلسل على أكثر من مجال ببساطة ووضوح وكما ذكرت معلومات عامة وسطحية وكانت كالتالي:\nبداية بمقدمة عن معالجة المياة والملوثات المعتاد وجودها بالماء وخطرها\nبعد ذلك تم التطرق الى طرق المعالجة في مصانع معالجة المياة\nاضافة الى ذلك تم التطرق الى كل ملوث على حدة و السبل المؤدية الى معالجته يتخلل ذلك بضعا من الأرقام والإحصائيات.\n\nطريقة الدراسة لهذه المادة قد لا يفضله شريحة كبيرة من الطلاب, بحيث أنها تعتمد على الفهم و الحفظ لمعلومات تعتبر كثيرة نوعا ما.\n\nالمادة معلوماتية أكثر من كونها حل المسائل, المسائل تعتبر قليلة جدا وذلك يعود لصلب الموضوع الذي لا يعتمد كثيرا على الارقام والحسابات.\nكمنهدس كيميائي يهمك كثيرا الالمام بعامية المواضيع التي تم التطرق إليها.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/che-471-process-water-pollution-control/152290/4", "user": "user10077", "ts": 1485017626000, "tid": 152290, "pn": 4}}', 1485017626000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
